mapper.select:
SELECT count(*)
FROM job.job_run
WHERE app_name = #{appName}
  AND schedule_key = #{scheduleKey}
  AND job_key = #{jobKey}
  AND job_definition_version = #{definitionVersion}

SELECT run.id AS run_id,
       run.scheduled_fire_time AS scheduled_at,
       run.status,
       run.completed_at,
       node.output_json::text AS output_json
FROM job.job_run run
LEFT JOIN job.job_run_node node
  ON node.run_id = run.id
 AND node.node_key = #{nodeKey}
 AND node.status = 'SUCCEEDED'
WHERE run.app_name = #{appName}
  AND run.schedule_key = #{scheduleKey}
  AND run.job_key = #{jobKey}
  AND run.job_definition_version = #{definitionVersion}
ORDER BY run.scheduled_fire_time DESC, run.id DESC
OFFSET #{page.offset} LIMIT #{page.size}

SELECT id, job_key, job_definition_version,
       input_json::text AS input_json, output_json::text AS output_json, status
FROM job.job_run
WHERE app_name = #{appName}
  AND system_identity = #{systemIdentity}
  AND job_key = #{jobKey}
  AND work_key = #{workKey.value}
  AND target_instance_id IS NOT DISTINCT FROM #{targetInstanceId}
  AND status IN ('QUEUED', 'RUNNING')
ORDER BY id LIMIT 1

SELECT instance_id, generation_id
FROM job.job_instance
WHERE app_name = #{appName}
  AND expires_at > #{now}
  AND jsonb_exists(capabilities_json, #{capabilityCode})
ORDER BY instance_id

mapper.delete:
DELETE FROM job.job_instance
WHERE app_name = #{appName}
  AND instance_id = #{instanceId}
  AND generation_id = #{generationId}

mapper.select:
SELECT id, targets_json::text AS targets_json
FROM job.job_dispatch
WHERE app_name = #{appName}
  AND schedule_key = #{scheduleKey}
  AND scheduled_fire_time = #{scheduledAt}

SELECT id FROM job.job_delivery
WHERE app_name = #{appName}
  AND system_identity = #{systemIdentity}
  AND job_key = #{jobKey}
  AND work_key = #{workKey.value}
  AND target_instance_id = #{targetInstanceId}
  AND status IN ('READY', 'RUNNING')
ORDER BY id LIMIT 1

mapper.update:
UPDATE job.job_delivery
SET lease_until = #{leaseUntil}
WHERE id = #{deliveryId}
  AND target_instance_id = #{instanceId}
  AND (target_generation_id IS NULL OR target_generation_id = #{generationId})
  AND status = 'RUNNING'
  AND lease_until > #{now}

UPDATE job.job_delivery
SET status = #{status}, error_summary = #{error},
    completed_at = #{completedAt}, lease_until = NULL
WHERE id = #{deliveryId}
  AND target_instance_id = #{instanceId}
  AND (target_generation_id IS NULL OR target_generation_id = #{generationId})
  AND status = 'RUNNING'
  AND lease_until > #{completedAt}

UPDATE job.job_delivery
SET status = 'FAILED', error_summary = '目标实例等待期限已到', completed_at = #{now}
WHERE app_name = #{appName}
  AND ((status = 'READY' AND expires_at <= #{now})
    OR (status = 'RUNNING' AND lease_until <= #{now}))

mapper.delete:
DELETE FROM job.job_delivery
WHERE app_name = #{appName} AND status IN ('SUCCEEDED', 'FAILED')
  AND completed_at < #{completedBefore}

mapper.select:
SELECT id FROM job.job_run
WHERE app_name = #{appName}
  AND schedule_key = #{scheduleKey}
  AND scheduled_fire_time = #{scheduledAt}
  AND target_instance_id IS NOT DISTINCT FROM #{targetInstanceId}
ORDER BY id LIMIT 1

SELECT id FROM job.job_run
WHERE app_name = #{appName} AND id = #{runId}
FOR UPDATE

mapper.update:
WITH RECURSIVE failed AS (
    UPDATE job.job_run_node
    SET status = 'FAILED', error_summary = #{error}, completed_at = #{failedAt},
        lease_owner = NULL, lease_until = NULL
    WHERE id = #{nodeId} AND run_id = #{runId} AND status = 'RUNNING'
      AND lease_owner = #{workerId} AND attempt_count = #{attempt}
    RETURNING id, run_id
), dependent AS (
    SELECT node_id AS id FROM job.job_run_dependency WHERE depends_on_node_id IN (SELECT id FROM failed)
    UNION
    SELECT dependency.node_id FROM job.job_run_dependency dependency
    JOIN dependent ON dependency.depends_on_node_id = dependent.id
), cancelled AS (
    UPDATE job.job_run_node SET status = 'CANCELLED', completed_at = #{failedAt}
    WHERE id IN (SELECT id FROM dependent) AND status IN ('WAITING', 'READY')
), run_updated AS (
    UPDATE job.job_run SET status = 'FAILED', error_summary = #{error}, completed_at = #{failedAt}
    WHERE id IN (SELECT run_id FROM failed) AND status IN ('QUEUED', 'RUNNING')
)
UPDATE job.job_run_attempt
SET status = 'FAILED', error_summary = #{error}, completed_at = #{failedAt}
WHERE node_id IN (SELECT id FROM failed) AND attempt_number = #{attempt}
  AND worker_id = #{workerId} AND status = 'RUNNING'

WITH recovered AS (
    UPDATE job.job_run_node SET status = 'READY', available_at = #{availableAt},
        lease_owner = NULL, lease_until = NULL, error_summary = 'Job worker 租约到期'
    WHERE id = #{nodeId} AND status = 'RUNNING' AND attempt_count = #{attempt}
      AND lease_owner = #{workerId} AND lease_until = #{leaseUntil}
    RETURNING id
)
UPDATE job.job_run_attempt SET status = 'ABANDONED', completed_at = #{now},
    error_summary = 'Job worker 租约到期'
WHERE node_id IN (SELECT id FROM recovered) AND attempt_number = #{attempt}
  AND worker_id = #{workerId} AND status = 'RUNNING'

WITH expired AS (
    UPDATE job.job_run
    SET status = 'FAILED',
        error_summary = '目标实例等待期限已到',
        completed_at = #{now}
    WHERE app_name = #{appName}
      AND status = 'QUEUED'
      AND target_expires_at <= #{now}
    RETURNING id
)
UPDATE job.job_run_node
SET status = 'CANCELLED', completed_at = #{now}
WHERE run_id IN (SELECT id FROM expired)
  AND status IN ('WAITING', 'READY')

mapper.select:
SELECT id FROM job.job_run
WHERE app_name = #{appName} AND status = 'SUCCEEDED' AND completed_at < #{completedBefore}
ORDER BY completed_at, id LIMIT #{limit}
FOR UPDATE SKIP LOCKED
